function namesFor(flags) {
  const result = [];
  for (const flag of flags) {
    result.push(normalizeName(flag.name));
  }
  return result;
}

export function enabledFlagNames(flags) {
  const enabled = enabledEntries(flags);
  const names = namesFor(enabled);
